(async () => {
      try {
        await pedirParada({ lat: lugar.lat, lng: lugar.lng, motivo: describirLugar(lugar, categoria) })
        meshAlert(
          'Propuesta enviada',
          'Le avisamos al líder. Si la aprueba, el grupo recibe el lugar para ir todos.'
        )
      } catch (e) {
        meshAlert('No se pudo enviar', mensajeDeError(e))
      }
    })

(async () => {
      const pos = await posicionActual()
      if (!pos) {
        meshAlert(
          'Sin ubicación',
          'No pudimos obtener tu posición para registrar la parada. Revisá los permisos de ubicación.'
        )
        return
      }
      try {
        await registrarParada(categoria, pos, grupal)
      } catch (e) {
        meshAlert('No se pudo registrar la parada', mensajeDeError(e))
      }
    })

(async () => {
      try {
        await retomarViaje()
      } catch (e) {
        meshAlert('No se pudo retomar', mensajeDeError(e))
      }
    })

(async () => {
      try {
        await confirmarBien()
      } catch (e) {
        meshAlert('No se pudo confirmar', mensajeDeError(e))
      }
    })

(async () => {
      try {
        await confirmarMal()
      } catch (e) {
        meshAlert('No se pudo avisar al grupo', mensajeDeError(e))
      }
    })

(async () => {
      const pos = await posicionActual()
      try {
        await pedirParada({ lat: pos?.lat, lng: pos?.lng })
      } catch (e) {
        meshAlert('No se pudo enviar', mensajeDeError(e))
      }
    })

(async () => {
      const activa = await activarSeguirParada()
      if (!activa || !myPosition) return
      // Encuadre deliberado entre vos y la parada: como un arrastre manual,
      // pausa el modo "seguirme" para que no se pise con el próximo tick de posición.
      setSiguiendo(false)
      mapRef.current?.fitBoundsToCoords([
        [myPosition.lat, myPosition.lng],
        [activa.lat, activa.lng],
      ])
    })

(async () => {
      try {
        await responderSolicitud(solicitud.solicitudId, decision)
      } catch (e) {
        meshAlert('No se pudo responder', mensajeDeError(e))
        return
      }
      // Propuesta con lugar ("Cerca mío"): aprobar solo le avisa al que la pidió,
      // así que se abre la alerta ya armada para que el grupo reciba el lugar.
      // El pedido simple de parada manda la posición pero no un motivo: no aplica.
      if (decision !== 'aprobada' || solicitud.lat == null || solicitud.lng == null || !solicitud.motivo) {
        return
      }
      abrirAlertaConLugar({
        tipo: 'parada',
        mensaje: `Paramos: ${solicitud.motivo}.`,
        ubicacion: { lat: solicitud.lat, lng: solicitud.lng },
        nombreUbicacion: solicitud.motivo,
      })
    })

(async () => {
      try {
        const alerta = await publicarAlerta({
          tipo,
          mensaje: mensaje.trim() || undefined,
          lat: ubicacion?.lat,
          lng: ubicacion?.lng,
        })
        setComponiendoAlerta(false)
        // Con lugar, quien la crea también va: se le dibuja la ruta hasta ahí.
        // Si la ruta no se puede calcular, la alerta igual salió: no se avisa como error.
        if (alerta.lat != null && alerta.lng != null) {
          const activa = await seguirAlertaPropia(alerta).catch(() => null)
          if (activa && activa.polyline.length > 1) {
            // Encuadre deliberado, como en "Cerca mío": pausa el "seguirme".
            setSiguiendo(false)
            mapRef.current?.fitBoundsToCoords(activa.polyline)
          }
        }
      } catch (e) {
        meshAlert('No se pudo enviar la alerta', mensajeDeError(e))
      }
    })
